import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    order_qty = {}     # id -> remaining qty
    order_side = {}     # id -> 'buy'/'sell'
    order_price = {}    # id -> price (for resting limit orders)
    order_status = {}   # id -> 'active','cancelled','filled'

    seq_counter = 0

    def add_to_book(side, oid, price, qty, seq):
        order_qty[oid] = qty
        order_side[oid] = side
        order_price[oid] = price
        order_status[oid] = 'active'
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if order_status.get(oid) == 'active':
                order_status[oid] = 'cancelled'
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_seq, top_id = heap[0]
            else:
                neg_price, top_seq, top_id = heap[0]
                top_price = -neg_price

            # discard stale/invalid entries
            if order_status.get(top_id) != 'active' or order_qty.get(top_id, 0) <= 0:
                heapq.heappop(heap)
                continue

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, order_qty[top_id])

            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            order_qty[top_id] -= trade_qty

            if order_qty[top_id] == 0:
                order_status[top_id] = 'filled'
                heapq.heappop(heap)
            # else: partially filled resting order stays at top of heap
            # (still highest priority) for next iteration

        if typ == 'limit':
            if remaining > 0:
                add_to_book(side, oid, price, remaining, seq)
            else:
                order_status[oid] = 'filled'
                order_qty[oid] = 0
        else:
            # ioc or market: discard remainder, do not rest
            order_qty[oid] = 0
            order_status[oid] = 'filled' if remaining == 0 else 'cancelled'

    return trades

